 camera(position,look,player,camera={fov:55,aspect:1.6},force=false){if(this.neighbourActivity){const n=this.neighbours[this.neighbourActivity.index];look.copy(player.position).lerp(n.pos,.5).add(new THREE.Vector3(0,1.4,0));position.copy(look).add(new THREE.Vector3(0,2.4,8));return true;}if(!this.activity&&!this.toyView){this.view.reset();return false;}const routine=['fridge','wash'].includes(this.activity),focus=routine?[this.activity==='fridge'?this.fridgeRoot:this.washRoot]:this.toyView?[this.toyView.object]:this.home.focusObjects(this.activity);const roots=[...this.town.house.children.filter(o=>o!==this.home.root&&o!==this.routineRoot).flatMap(o=>(o.userData.homeDepth||['Owned playmat toys','Home family'].includes(o.name))?o.children:[o]),...this.home.root.children,...this.routineRoot.children];this.town.house.updateMatrixWorld(true);this.view.prepare(roots,player,focus);const preferred=this.toyView?player.position.clone().add(new THREE.Vector3(4,5,7)):routine?player.position.clone().add(new THREE.Vector3(5,3,6)):this.toWorld(this.home.camera.pos);this.view.solve(camera,preferred,look,position,{key:(this.activity||this.toyView?.id),force});return true;}
